import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.DqVSm8kp.js";const p=JSON.parse('{"title":"Découvert avec LLMxRay","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/showcase.md","filePath":"fr/community/showcase.md"}'),n={name:"fr/community/showcase.md"};function o(i,e,l,u,c,d){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="decouvert-avec-llmxray" tabindex="-1">Découvert avec LLMxRay <a class="header-anchor" href="#decouvert-avec-llmxray" aria-label="Permalink to &quot;Découvert avec LLMxRay&quot;">​</a></h1><p>Une sélection de découvertes intéressantes, de comportements surprenants et d&#39;observations précieuses faites par la communauté grâce à LLMxRay.</p><h2 id="comment-soumettre" tabindex="-1">Comment soumettre <a class="header-anchor" href="#comment-soumettre" aria-label="Permalink to &quot;Comment soumettre&quot;">​</a></h2><p>Vous avez trouvé quelque chose d&#39;intéressant ? Nous serions ravis de le mettre en avant.</p><ol><li>Ouvrez une issue <a href="https://github.com/LogneBudo/llmxray/issues/new?template=showcase-submission.yml" target="_blank" rel="noreferrer">Soumission Vitrine</a></li><li>Remplissez le formulaire structuré : ce que vous avez trouvé, quels modèles, comment reproduire</li><li>Incluez des captures d&#39;écran de LLMxRay si possible</li><li>Nous examinerons votre soumission et l&#39;ajouterons à cette page</li></ol><hr><h2 id="decouvertes-mises-en-avant" tabindex="-1">Découvertes mises en avant <a class="header-anchor" href="#decouvertes-mises-en-avant" aria-label="Permalink to &quot;Découvertes mises en avant&quot;">​</a></h2><h3 id="effet-de-seuil-de-la-temperature-sur-la-generation-de-code" tabindex="-1">Effet de seuil de la température sur la génération de code <a class="header-anchor" href="#effet-de-seuil-de-la-temperature-sur-la-generation-de-code" aria-label="Permalink to &quot;Effet de seuil de la température sur la génération de code&quot;">​</a></h3><p><strong>Contributeur :</strong> LogneBudo | <strong>Modèles :</strong> Mistral 7B | <strong>Date :</strong> Mars 2026</p><p>En utilisant la fonctionnalité Compare avec le preset Temperature Sweep, nous avons constaté que Mistral 7B produit du code Python nettement plus précis à une température de 0.2 qu&#39;à 0.7. À 0.7, le modèle introduit des noms de variables créatifs mais incorrects et hallucine occasionnellement des méthodes d&#39;API. La coloration de confiance des tokens dans Chat Diagnostics a rendu cette incertitude visible — les tokens de la sortie à 0.7 affichaient systématiquement une confiance plus faible (davantage orange) autour des appels de fonctions.</p><h3 id="la-profondeur-de-reflexion-de-deepseek-r1-varie-selon-le-type-de-question" tabindex="-1">La profondeur de réflexion de DeepSeek-R1 varie selon le type de question <a class="header-anchor" href="#la-profondeur-de-reflexion-de-deepseek-r1-varie-selon-le-type-de-question" aria-label="Permalink to &quot;La profondeur de réflexion de DeepSeek-R1 varie selon le type de question&quot;">​</a></h3><p><strong>Contributeur :</strong> LogneBudo | <strong>Modèles :</strong> DeepSeek-R1 7B | <strong>Date :</strong> Mars 2026</p><p>L&#39;onglet Reasoning a révélé que les blocs <code>&lt;think&gt;</code> de DeepSeek-R1 sont considérablement plus longs pour les problèmes mathématiques (GSM8K) que pour le rappel factuel (TruthfulQA). Sur GSM8K, le modèle effectue en moyenne 12 à 15 étapes de raisonnement avec vérification arithmétique explicite. Sur TruthfulQA, il utilise généralement 2 à 3 étapes avant de s&#39;engager sur une réponse. Cela était visible dans les résultats de Benchmark — GSM8K présentait un TTFT plus élevé mais aussi une meilleure précision lorsque le budget de réflexion n&#39;était pas plafonné.</p><h3 id="impact-de-la-quantification-sur-la-precision-des-benchmarks" tabindex="-1">Impact de la quantification sur la précision des benchmarks <a class="header-anchor" href="#impact-de-la-quantification-sur-la-precision-des-benchmarks" aria-label="Permalink to &quot;Impact de la quantification sur la précision des benchmarks&quot;">​</a></h3><p><strong>Contributeur :</strong> LogneBudo | <strong>Modèles :</strong> Llama 3.2 3B (Q4_0 vs Q8_0) | <strong>Date :</strong> Mars 2026</p><p>L&#39;exécution de la même suite ARC-Challenge sur Llama 3.2 en Q4_0 et Q8_0 via la page Benchmark a montré une baisse de précision de 4.2 % en Q4_0. La ventilation par catégorie a révélé que cette baisse se concentrait sur les questions de physique (chute de 7.1 %) tandis que les questions de biologie étaient à peine affectées (0.8 % de baisse). Les distributions de logprob ont confirmé que le Q4_0 était globalement moins confiant, mais l&#39;écart de confiance se creusait spécifiquement sur les questions nécessitant un raisonnement numérique en plusieurs étapes.</p><hr><p><em>Vous souhaitez voir votre découverte ici ? <a href="https://github.com/LogneBudo/llmxray/issues/new?template=showcase-submission.yml" target="_blank" rel="noreferrer">Soumettez une issue Vitrine</a>.</em></p>',18)])])}const h=t(n,[["render",o]]);export{p as __pageData,h as default};
